import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"震為雷","description":"周易折中 - 震為雷","frontmatter":{"title":"震為雷","description":"周易折中 - 震為雷"},"headers":[],"relativePath":"classics/zhezhong/057.md","filePath":"classics/zhezhong/057.md"}'),h={name:"classics/zhezhong/057.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="震為雷" tabindex="-1">震為雷 <a class="header-anchor" href="#震為雷" aria-label="Permalink to “震為雷”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈震〉序卦主器者莫若長子，故受之以《震》。《鼎》者，器也。《震》為長男，故取主器之義而繼《鼎》之後。長子傳國家繼位號者也，故為主器之主。序卦取其一義之大者為相繼之義。《震》之為卦，一陽生於二陰之下，動而上者也，故為《震》。震動也。不曰動者，《震》有動而奮發、震驚之義。乾坤之交，一索而成《震》，生物之長也，故為長男。其象則為雷，其義則為動。雷有震奮之象，動為驚懼之義。</p><p>震：亨。震來虩虩，笑言啞啞。震驚百里，不喪匕鬯。</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>震動也，一陽始生於二陰之下，震而動也。其象為雷，其屬為長子。震有亨道，震來當震之來時也，虩虩恐懼驚顧之貌。震驚百里，以雷言。匕所以舉鼎實，鬯以秬黍酒和鬱金所以灌地降神者也。不喪匕鬯，以長子言也。此卦之佔為能恐懼則致福，而不失其所主之重。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>陽生於下而上進，有亨之義。又震為動，為恐懼，為有主。震而奮發，動而進，懼而修，有主而保大，皆可以致亨。故震則有亨。當震動之來，則恐懼不敢自寧，旋顧周慮，虩虩然也。虩虩，顧慮不安之貌。蠅虎謂之虩者，以其周環顧慮不自寧也。處震如是，則能保其安裕，故笑言啞啞。啞啞，言笑和適之貌。震驚百里，不喪匕鬯，言震動之大而處之之道。動之大者莫若雷，震為雷，故以雷言。雷之震動，驚及百里之遠人，無不懼而自失。雷聲所及百里也，唯宗廟祭祀執匕鬯者，則不致於喪失。人之致其誠敬，莫如祭祀。匕以載鼎實升之於爼，鬯以灌地而降神。方其酌祼以求神，薦牲而祈享，盡其誠敬之心，則雖雷震之威不能使之懼而失守。故臨大震懼能安而不自失者，唯誠敬而已。此處震之道也。卦才無取，故但言處震之道。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>幹氏寶曰 ：祭禮薦陳甚多，而經獨言不喪匕鬯者，匕牲體薦，鬯酒人君所自親也。</p></li><li><p>胡氏瑗曰 ：百里雷聲之所及也。匕者，宗廟之器，以棘木為之，似畢而無兩岐，所以舉鼎之實而升於爼也。鬯者，以鬱金草和酒而有芬芳調鬯之氣。</p></li><li><p>胡氏炳文曰 ：震驚百里，以震為雷取象；不喪匕鬯，以長子主器取象。震亨謂震有亨之道，又自以震來虩虩釋震字，以笑言啞啞以下釋亨字。</p></li><li><p>蔡氏清曰 ：震來當震之來時也，以心言，謂事之可懼而吾懼之也。其震懼之也，虩虩然。非震來而後虩虩也，虩虩所以狀其震來也。或曰“來者自外來也”，故爻雲“震來厲”，又云“震不於其躬，於其鄰”。此說非惟昧卦辭“震來”之義，亦失卦名“震”字之義矣。蓋震之來，來猶至也，固亦有其事。然震之至，則在我也。六二“震來厲”，謂當震之來而危厲，此震來正與卦辭旨同。至於“震不於其躬”，本義分明有“恐懼脩省”字，其與卦辭同益明矣。凡有所事者，皆當懼。懼便是震來也。君子之心常存敬畏，執事便敬，所以致福而不失其所主之重。又曰：震來虩虩以心言，震驚百里以事言，不喪匕鬯不懼也。不懼由於能懼。</p></li><li><p>餘氏本曰 ：震驚百里只是足“笑言啞啞”一句意，大意謂人平時若能恐懼，則可以致福，雖卒然禍變之來，亦無可畏也。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>震來之義，蔡氏得之矣。</p><p>象曰：洊雷震，君子以恐懼脩省</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>洊，重襲也。上下皆震，故為洊雷。雷重仍，則威益盛。君子觀洊雷威震之象，以恐懼自脩飭，循省也。君子畏天之威，則脩正其身，思省其過咎而改之。不唯雷震，凡遇驚懼之事，皆當如是。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>項氏安世曰 ：恐懼脩省，所謂洊也。人能恐懼，則既震矣；又脩省焉，洊在其中矣。</p></li><li><p>胡氏炳文曰 ：恐懼作於心，脩省見於事。脩，克治之功；省，審察之力。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>恐懼脩省者，君子之洊雷也。非遇雷震而恐懼也，須從項氏之說理解。</p><p>彖曰：震，亨</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>震有亨道，不待言也。</p><p>震來虩虩，恐致福也；笑言啞啞，後有則也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>恐致福，恐懼以致福也；則，法也。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>震自有亨之義，非由卦才。震來而能恐懼，自修自慎，則可反致福吉。笑言啞啞，言自若也。由能恐懼而後自處有法則也，有則則安而不懼矣，處震之道也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>董氏曰 ：致福雲者，見君子常以危為安也。有則雲者，見君子不以忽忘敬也。</p></li><li><p>李氏過曰 ：有則，謂君子所履出處語默皆有常則，不以恐懼而變也。</p></li></ul><p>震驚百里，驚遠而懼邇也；出可以守宗廟社稷，以為祭主也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>程子以為“邇也”下，脫“不喪匕鬯”四字，今從之。“出”，謂繼世而主祭也。或雲，出即鬯字之誤。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>雷之震及於百里，遠者驚，邇者懼，言其威遠大也。彖文脫“不喪匕鬯”一句，卦辭雲“不喪匕鬯”，本謂誠敬之至，威懼不能使之自失。彖以長子宜如是，因承上文用長子之義通解之，謂其誠敬能不喪匕鬯，則君出而可以守宗廟社稷為祭主也。長子如是，而後可以守世祀承國家也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類雲 ：震便自是亨，震來虩虩是恐懼顧慮，而後便笑言啞啞；震驚百里便也不喪匕鬯。文王語已是解震亨了，孔子又自說長子事。</p></li><li><p>丘氏富國曰 ：驚者，卒然遇之而動乎外；懼者，惕然畏之而變於中。</p></li><li><p>張氏清子曰 ：出者，即說卦“帝出乎震”之謂；主者，即序卦“主器莫若長子”之謂。若舜之“烈風雷雨弗迷”，可以出而嗣位矣。</p></li><li><p>蔡氏清曰 ：懼深於驚，遠近之別也。</p></li><li><p>楊氏啟新曰 ：幹者自強而已矣，而曰惕；震者動而已矣，而曰懼。惕之為強也，見惕之非惴懾也；懼之為動也，見懼之非驚恐也。</p></li></ul><p>初九：震來虩虩，後笑言啞啞，吉</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>成震之主，處震之初，故其佔如此。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>初九，成震之主，致震者也。在卦之下，處震之初，知震之來當震之始。若能以為恐懼而周旋顧慮，虩虩然不敢寧止，則終必保其安吉。故後笑言啞啞也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>石氏介曰 ：初九有陽明之德，居震之始，是能先戒懼者，故繇彖所言此爻當之。</p></li><li><p>胡氏炳文曰 ：初九在內卦之內，震之主也，故辭與卦同。蓋震之用在下，而重震之初又最下者，所以為震之主也。</p></li></ul><p>象曰：震來虩虩，恐致福也；笑言啞啞，後有則也</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>震來而能恐懼周顧，則無患矣。是能因恐懼而反致福也。因恐懼而自脩省，不敢違於法度，是由震而後有法則，故能保其安吉而笑言啞啞也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li>範氏仲淹曰 ：君子之懼於心也，思慮必愼，其始則百志弗違於道；懼於身也，進退不履於危，則百行弗罹於禍。故初九震來而致福，愼於始也。</li></ul><p>六二：震來厲，億喪貝，躋於九陵，勿逐，七日得</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>六二乘初九之剛，故當震之來而危厲也。億字未詳，又當喪其貨貝而升於九陵之上。然柔順中正，足以自守，故不求而自獲也。此爻佔具象中，但九陵七日之象則未詳耳。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>六二居中得正，善處震者也。而乘初九之剛，九震之主，震剛動而上奮，孰能御之？厲猛也，危也。彼來既猛，則已處危矣。億度也，具所有之資也。躋，升也。九陵，陵之高也。逐，往追也。以震來之厲，度不能當而必喪其所有，則升至高以避之也。九言其重，岡陵之重高之至也，九重之多也，如九天九地也。勿逐，七日得。二之所貴者中正也。遇震懼之來，雖量勢巽避，當守其中正，無自失也。億之必喪也，故遠避以自守，過則復其常矣。是勿逐而自得也。逐即物也，以已即物失其守矣，故戒勿逐。避遠自守，處震之大方也。如二者當危懼而善處者也。卦位有六七，乃更始事既終，時既易也。不失其守，雖一時不能御其來，然時過事已，則復其常，故云七日得。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>鄭氏汝諧曰 ：億度也，度寶貨之可喪而喪之，不憚九陵之險而升之，避害以自全，靜退以觀變，事定則必得其所謂安利也。</p></li><li><p>楊氏簡曰 ：六二乘初九之剛，不可安處，故億喪具往而躋於九陵。雖今未得，至於歷七日，則時當得矣。勿用逐也。避難曲折有如此者，昔太王既不可御狄，不可安處，去而邑於岐山之下，而他日興周焉，此象也。</p></li><li><p>蔣氏悌生曰 ：億度也，事未至未著而先謀度之謂億。</p></li><li><p>楊氏啟新曰 ：喪自喪之也，躋於九陵，飄然遠舉之意。人之所以常蹈禍者，利耳。遠利而自處於高，豈惟無厲，所喪者可以不久而獲矣。</p></li></ul><p>象曰：震來厲，乘剛也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>當震而乘剛，是以彼厲而已危。震剛之來，其可御乎？</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰 ：屯六二、豫六五、噬嗑六二、困六三、震六二皆言乘剛，惟困六三乘坎之中爻，其餘皆乘震之初也。</li></ul><p>六三：震蘇蘇，震行無眚</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>蘇蘇，緩散自失之狀。以陰居陽，當震時而居不正，是以如此。佔者若因懼而能行，以去其不正，則可以無眚矣。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>蘇蘇，神氣緩散自失之狀。三以陰居陽，不正處。不正於平時且不能妄，況處震乎？故其震懼而蘇蘇然。若因震懼而能行去不正而就正，則可以無過眚（過也）。三行則至四正也，動以就正為善，故二“勿逐”則自得，三能行則無眚。以不正而處震，懼有眚可知。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>趙氏光大曰 ：當震時而懼益甚，精神渙散，故為震蘇蘇之象。然天下不患有憂懼之時，而患無脩省之功。若能因此懼心而行，則持身無妄動，應事有成規，又何眚之有？</p></li><li><p>楊氏啟新曰 ：震而不行，徒震耳。行者改圖也，此恐懼所以脩省也。</p></li></ul><p>象曰：震蘇蘇，位不當也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>其恐懼自失，蘇蘇然。由其所處不當故也，不中不正，其能安乎？</p><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>震當虩虩，不當蘇蘇。六三當重震之閒，正奮厲以有為之時也，而以陰不中正處之，至於蘇蘇緩散，故曰位不當。</p><p>九四：震遂泥</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>以剛處柔，不中不正，陷於二陰之閒，不能自震也。遂者，無反之意；泥，滯溺也。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>九四居震動之時，不中不正，處柔失剛健之道，居四無中正之德，陷溺於重陰之閒，不能自震奮者也。故云“遂泥”，泥滯溺也。以不正之陽而上下重陰，安能免於泥乎？遂無反之意，處震懼則莫能守也，欲震動則莫能奮也。震道亡矣，豈復能光亨也？</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>項氏安世曰 ：初九以一陽動乎二陰之下，得震之本象，故其福與卦辭合。九四以一陽動乎四陰之中，則震變成坎，震而遂陷於泥也。</p></li><li><p>胡氏炳文曰 ：初與四皆震之所以為震者，然震之用在下，四溺於陰柔之中，故震之亨在初而不在四。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>卦爻“震”字雖以人心為主，然震之本象則雷也。凡雷乘陽氣而動，然所乘之氣不同，故邵子曰“水雷玄，火雷赫，土雷連，石雷霹”。蓋雷聲有動而不能發逹者，陷於陰氣也。此爻陽動於四陰之中，故有“震遂泥”之象。在人則志氣未能自遂，乃困心衡慮之時也。</p><p>象曰：震遂泥，未光也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>陽者剛物，震者動義。以剛處動，本有光亨之道，乃失其剛正而陷於重陰，以致遂泥，豈能光也？雲“未光”，見陽剛本能震也，以失德故泥耳。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>四有剛德，非失德者。此言未光，蓋志氣未能自遂，行拂亂其所為耳，與噬嗑九四之未光同，皆謂所處者未能遂其所志，非兌上未光之比。</p><p>六五：震往來厲，億無喪，有事</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>以六居五而處震時，無時而不危也。以其得中，故無所喪而能有事。佔者不失其中，則雖危無喪矣。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>六五雖以陰居陽，不當位為不正，然以柔居剛，又得中，乃有中德者也。不失中則不違於正矣，所以中為貴也。諸卦二五雖不當位，多以中為美；三四雖當位，或以不中為過。中常重於正也，蓋中則不違於正，正不必中也。天下之理莫善於中，於六二、六五可見。五之動，上往則柔不可居動之極，下來則犯剛，是往來皆危也。當君位，為動之主，隨宜應變，在中而已。故當億度無喪，失其所有之事而已。所有之事，謂中德。苟不失中，雖有危，不至於兇也。億度，謂圖慮求不失中也。五所以危，由非剛陽而無助，若以剛陽有助為動之主，則能亨矣。往來皆危時，則甚難，但期於不失中，則可自守。以柔主動，固不能致亨濟也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>虞氏翻曰 ：可以守宗廟社稷，為祭主，故無喪有事也。</p></li><li><p>項氏安世曰 ：二居下震之上，故稱“來”；五居重震之上，故稱“往來”。億度也，二五之厲即震之恐懼也，二五之億即震之脩省也。</p></li><li><p>熊氏良輔曰 ：震往亦厲，來亦厲，皆以危懼待之，故能無喪有事。蓋不失其所有也。此卦辭所謂“不喪匕鬯，能主器以君天下”者與。</p></li><li><p>俞氏琰曰 ：二曰“震來”，指初之來。以五視初，則初之始震為既往，四之洊震為復來。五蓋震往而復來之時也。“有事”謂有事於宗廟社稷也。震之主爻在初，而“無喪有事”乃歸之五，五乃震之君也。案春秋凡祭祀皆曰“有事”，故此“有事”謂祭也。二五之震同，其有中德而能億度於事理者亦同。然二喪具而五無喪者，二居下位，所有者具耳；五居尊，所守者則宗廟社稷也，具可喪也，宗廟社稷可以失守乎？故二以喪貝為中，五以無喪有事為中。</p></li></ul><p>象曰：震往來厲，危行也；其事在中，大無喪也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>往來皆厲，行則有危也。動皆有危，唯在無喪其事而已。其事謂中也，能不失其中，則可自守也。大無喪，以無喪為大也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰 ：無喪有事，猶雲不失其所有也。以其乘剛故危，以其在中故無喪。禍至與不至皆懼，則無喪有事。</p></li><li><p>郭氏雍曰 ：二以來厲而喪貝，則五之往來皆厲，宜其大有喪也。六五位雖不正，而用中焉，其事既不失中道，雖涉危行，可以大無喪矣。</p></li></ul><p>上六：震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>以陰柔處震極，故為索索、矍矍之象。以是而行，其兇必矣。然能及其震未及身之時，恐懼脩省，則可以無咎，而亦不能免於婚媾之有言。戒佔者當如是也。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>索索，消索不存之狀，謂其志氣如是。六以陰柔居震動之極，其驚懼之甚，志氣殫索也。矍矍，不安定貌，志氣索索則視瞻徊徨。以陰柔不中正之質而處震動之極，故徵則兇也。震之及身乃於其躬也，不於其躬謂未及身也。鄰者，近於身者也。能震懼於未及身之前，則不至於極矣，故得無咎。苟未至於極，尚有可改之道。震終當變柔，不固守，故有畏鄰戒而能變之義。聖人於震終示人知懼能改之義為勸，深矣。婚媾，所親也，謂同動者有言，有怨咎之言也。六居震之上，始為眾動之首，今乃畏鄰戒而不敢進，與諸處震者異矣，故婚媾有言也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>鄭氏汝諧曰 ：上以陰柔之資而居一卦之上，其中無所得，不能自安，故震索索而氣不充，視矍矍而神不固。人之過於恐懼者固無足取，若能舉動之際，睹事之未然而知戒，亦聖人之所許也。</p></li><li><p>趙氏光大曰 ：陰處震極，故當震之來，志氣消沮，瞻視彷徨，驚懼之甚也。以是而行，其志先亂，兇也。所以然者，以不能圖之於早也。若震未及身而方及鄰之時，恐懼脩省，豫為之圖，則自無索索、矍矍之咎矣。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>此“婚媾有言”與《夬》四“聞言不信”同，皆佔戒之外反言以決之之辭也。瑣瑣姻婭，見識凡近，當禍患之未至，則相誘以晏安而已爾，安能為人深謀長慮而相與儆戒於未然乎？</p><p>象曰：震索索，中未得也；雖兇無咎，畏鄰戒也</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>中，謂中心。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>所以恐懼自失如此，以未得於中道也。謂過中也，使之得中，則不至於索索矣。極而復徵，則兇也。若能見鄰戒而知懼，變於未極之前，則無咎也。上六動之極，震極則有變義也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>吳氏澄曰 ：畏鄰戒，謂因鄰之戒而知畏也</p></li><li><p>龔氏煥曰 ：中未得者，處震之極，志氣消索，中無所主也。若能畏懼鄰爻之戒，及時調整自己的行為，則可避免災禍，達到無咎的境界。</p></li></ul>',114)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
